236	     * email is present; add 1 when {@code namesakeCount} is 0; capped at 3. Level 4 is reserved for
237	     * tenure and is never produced here.
238	     */
239	    public int getMembershipLevel() {
240	        int level = 1;
241	        boolean hasEmail = this.email != null && !this.email.isBlank();
242	        if (hasEmail) {
243	            level++;
244	        }
245	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
246	        if (unique) {
247	            level++;
248	        }
249	        return Math.min(level, 3);
250	    }
