252	    /**
253	     * Fixed city-to-region table mapping each known city to its canonical region string.
254	     */
255	    private static final Map<String, String> CITY_REGION = Map.of(
256	        "Sydney", "NSW",
257	        "Melbourne", "VIC",
258	        "Brisbane", "QLD");
259	
260	    /**
261	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
262	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
263	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
264	     */
265	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
266	        "NSW", new int[] {2000, 2099},
267	        "VIC", new int[] {3000, 3099},
268	        "QLD", new int[] {4000, 4099});
269	
270	    /**
271	     * The canonical region for {@code city} derived from the fixed city-to-region table
272	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
273	     * city is not in the table. The single source of truth for the create-time postcode range check in
274	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
275	     */
276	    public static String regionOf(String city) {
277	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
278	    }
279	
280	    /**
281	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
282	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
283	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
284	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
285	     * postcode range check.
286	     */
287	    public static int[] postcodeRangeOf(String region) {
288	        return REGION_POSTCODES.get(region);
289	    }
290	
291	    /**
292	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
293	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
294	     * range.
295	     */
296	    public static String regionOfPostcode(String postcode) {
297	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
298	            return null;
299	        }
300	        int value = Integer.parseInt(postcode);
301	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
302	            int[] range = entry.getValue();
303	            if (value >= range[0] && value <= range[1]) {
304	                return entry.getKey();
305	            }
306	        }
307	        return null;
308	    }
309	
310	    /**
311	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
312	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
313	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
314	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
315	     * customer code is assigned.
316	     */
317	    public String getLocality() {
318	        if (this.customerCode == null) {
319	            return "UNKNOWN";
320	        }
321	        int dash = this.customerCode.indexOf('-');
322	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
323	    }
324	
325	    /**
326	     * The single Luhn check digit (0-9) computed over the digits contained in the
327	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
328	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
329	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
330	     */
331	    public int getCheckDigit() {
332	        String code = this.customerCode;
333	        if (code == null) {
334	            return 0;
335	        }
336	        int sum = 0;
337	        boolean dbl = true;
338	        for (int i = code.length() - 1; i >= 0; i--) {
339	            char c = code.charAt(i);
340	            if (c < '0' || c > '9') {
341	                continue;
342	            }
343	            int d = c - '0';
344	            if (dbl) {
345	                d *= 2;
346	                if (d > 9) {
347	                    d -= 9;
348	                }
349	            }
350	            sum += d;
351	            dbl = !dbl;
352	        }
353	        return (10 - (sum % 10)) % 10;
354	    }
355	
356	    /**
357	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
358	     * {@code "PHONE"}.
359	     */
360	    public String getContactPreference() {
361	        boolean hasEmail = this.email != null && !this.email.isBlank();
362	        return hasEmail ? "EMAIL" : "PHONE";
363	    }
364	
365	    /**
366	     * The single canonical format of an owner's identity key — the one value all duplicate detection is
367	     * expressed through: {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The
368	     * telephone and household id are used as given (they are expected to already be canonical: E.164 and
369	     * an assigned household id); the email is lower-cased here and a null/blank email, telephone or
370	     * household id contributes an empty component. This is the only place the {@code "|"}-join lives;
371	     * every producer of the key (the stored-owner {@link #getIdentityKey()} and the create-time check in
372	     * {@code OwnerIdentity}) routes through here so the formats cannot drift.
373	     */
374	    public static String identityKey(String telephone, String email, String householdId) {
375	        String tel = (telephone == null) ? "" : telephone;
376	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
377	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
378	        return tel + "|" + mail + "|" + household;
379	    }
380	
381	    /**
382	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and
383	     * household id via {@link #identityKey(String, String, String)}. Two owners are duplicates exactly
384	     * when their whole identity keys are equal.
385	     */
386	    public String getIdentityKey() {
387	        return identityKey(this.telephone, this.email, this.householdId);
388	    }
389	
390	    protected Set<Pet> getPetsInternal() {
391	        if (this.pets == null) {
392	            this.pets = new HashSet<>();
393	        }
394	        return this.pets;
395	    }
396	
397	    protected void setPetsInternal(Set<Pet> pets) {
398	        this.pets = pets;
399	    }
400	
401	    public List<Pet> getPets() {
402	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
403	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
404	        return Collections.unmodifiableList(sortedPets);
405	    }
406	
407	    public void setPets(List<Pet> pets) {
408	        this.pets = new HashSet<>(pets);
409	    }
410	
411	    public void addPet(Pet pet) {
412	        getPetsInternal().add(pet);
413	        pet.setOwner(this);
414	    }
415	
416	    /**
417	     * Return the Pet with the given name, or null if none found for this Owner.
418	     *
419	     * @param name to test
420	     * @return true if pet name is already in use
421	     */
422	    public Pet getPet(String name) {
423	        return getPet(name, false);
424	    }
425	
426	    /**
427	     * Return the Pet with the given name, or null if none found for this Owner.
428	     *
429	     * @param name to test
430	     * @return true if pet name is already in use
431	     */
432	    public Pet getPet(String name, boolean ignoreNew) {
433	        name = name.toLowerCase();
434	        for (Pet pet : getPetsInternal()) {
435	            if (!ignoreNew || !pet.isNew()) {
436	                String compName = pet.getName();
437	                compName = compName.toLowerCase();
438	                if (compName.equals(name)) {
439	                    return pet;
440	                }
441	            }
442	        }
443	        return null;
444	    }
445	
446	    public Pet getPet(Integer petId) {
447	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
448	    }
449	
450	    @Override
451	    public String toString() {
452	        return new ToStringCreator(this)
453	
454	            .append("id", this.getId())
455	            .append("new", this.isNew())
456	            .append("lastName", this.getLastName())
457	            .append("firstName", this.getFirstName())
458	            .append("address", this.address)
459	            .append("city", this.city)
460	            .append("telephone", this.telephone)
461	            .toString();
462	    }
463	}
